import { createHash } from 'node:crypto';
import type { KnowledgeCompilation, KnowledgeEntry, KnowledgeOverview, KnowledgeSource } from '../../src/knowledge/types.js';

/** Authored retrieval tasks, not expected answers generated by the selector under test. */
export interface KnowledgeContextGold {
  layer: 'A' | 'B' | 'C';
  id: string;
  /** Each fragment must survive verbatim; numbers, negations and code are intentional. */
  fragments: string[];
  sourceVersion?: number;
  startLine?: number;
  endLine?: number;
}

export interface KnowledgeContextReadStep {
  layer: 'A' | 'B';
  id: string;
  reason: string;
  version?: number;
  startLine?: number;
  endLine?: number;
  /** The task needs the whole requested range, rather than one relevant excerpt. */
  completeRange?: boolean;
  /** Evidence already obtained must remain available or be explicitly recoverable. */
  repeat?: boolean;
}

export interface KnowledgeContextTask {
  id: string;
  label: string;
  query: string;
  sources: KnowledgeSource[];
  compilation: KnowledgeCompilation;
  reads: KnowledgeContextReadStep[];
  gold: KnowledgeContextGold[];
  /** Irrelevant IDs must not take priority over the authored evidence. */
  noiseIds: string[];
  triggers: Array<'exact' | 'conflict' | 'candidate' | 'missing' | 'compare' | 'quote' | 'stale'>;
}

const createdAt = '2026-10-21T00:00:00.000Z';
function source(id: string, title: string, lines: string[], version = 1, verified = true, provenance?: string): KnowledgeSource {
  const content = lines.join('\n');
  return {
    id, title, version, verified, content, text: content, category: 'reference',
    provenance: provenance ?? `fixture://${id}/v${version}`,
    hash: createHash('sha256').update(content).digest('hex'), createdAt, processing: [],
  };
}
function entry(id: string, title: string, content: string, sources: KnowledgeSource[], ranges?: Array<[number, number]>): KnowledgeEntry {
  return { id, title, content, citations: sources.map((item, index) => ({ sourceId: item.id, sourceVersion: item.version,
    startLine: ranges?.[index]?.[0] ?? 1, endLine: ranges?.[index]?.[1] ?? item.text.split('\n').length })) };
}
function overview(id: string, title: string, summary: string, entryIds: string[]): KnowledgeOverview { return { id, title, summary, entryIds }; }
function compilation(entries: KnowledgeEntry[], summaries?: KnowledgeOverview[]): KnowledgeCompilation {
  return { entries, overview: summaries ?? entries.map(item => overview(`map-${item.id}`, item.title, item.content.split('\n')[0]!, [item.id])) };
}
const zhNoise = (topic: string, index: number) => `${topic}周报第${index}段：已整理人员分工、会议时间、采购流程与归档说明。本段只描述常规进展，不规定支付、恢复、权限、接口或服务上线阈值。`;
const enNoise = (index: number) => `Discussion ${index}: the dashboard team reviewed typography, component spacing, card placement, demo colors and navigation labels. No production API contract or billing retry policy is specified here.`;

function unrelated(count = 24): { sources: KnowledgeSource[]; entries: KnowledgeEntry[]; ids: string[] } {
  const sources = Array.from({ length: count }, (_, index) => source(`noise-${index}`, `办公与界面记录 ${index}`, Array.from({ length: 9 }, (_, line) => zhNoise('办公与界面', line))));
  const entries = sources.map(item => entry(`b-${item.id}`, item.title, item.text, [item]));
  return { sources, entries, ids: entries.map(item => item.id) };
}

function topicalTask(): KnowledgeContextTask {
  const noise = unrelated();
  const payment = source('payment-slo', '支付重试 SLO', [
    '# 支付重试与退款', '适用范围：已扣款但回执丢失的订单。',
    '最多重试 3 次，间隔分别为 2 秒、8 秒、30 秒；使用同一个 Idempotency-Key。',
    '退款请求不得自动重试；必须先查询退款状态。',
  ]);
  const b = entry('payment-retry', '支付重试与退款边界', payment.text, [payment]);
  return { id: 'multi-topic-routing', label: '多主题筛选与精确阈值', query: '为支付回执丢失场景写重试逻辑，列出次数、每次间隔、幂等键与退款例外。',
    sources: [...noise.sources, payment], compilation: compilation([...noise.entries.slice(0, 11), b, ...noise.entries.slice(11)]),
    reads: [{ layer: 'B', id: b.id, reason: 'task-detail' }, { layer: 'A', id: payment.id, reason: 'verify-exact-values', startLine: 2, endLine: 4 }],
    gold: [{ layer: 'C', id: `map-${b.id}`, fragments: [b.title] }, { layer: 'B', id: b.id, fragments: ['最多重试 3 次', '2 秒、8 秒、30 秒', '同一个 Idempotency-Key', '退款请求不得自动重试'] },
      { layer: 'A', id: payment.id, sourceVersion: 1, startLine: 2, endLine: 4, fragments: ['退款请求不得自动重试；必须先查询退款状态。'] }], noiseIds: noise.ids, triggers: ['exact'] };
}

