function longCodeTask(): KnowledgeContextTask {
  const code = [
    'export interface RetryRequest {', '  requestId: string;', '  signal: AbortSignal;', '  retryAfterMs?: number;', '}',
    ...Array.from({ length: 120 }, (_, index) => `// helper ${index}: rendering utilities are unrelated to authorization or network retries.`),
    'export async function submitInvoice(request: RetryRequest): Promise<Invoice> {',
    "  const response = await fetch('/api/v3/invoices:submit', {",
    "    method: 'POST',", "    headers: { 'Idempotency-Key': request.requestId, 'Content-Type': 'application/json' },",
    '    signal: request.signal,', '    body: JSON.stringify({ retryAfterMs: request.retryAfterMs ?? 1250 }),', '  });',
    "  if (response.status === 409) throw new Error('DUPLICATE_INVOICE');",
    "  if (response.status === 429) throw new Error('RETRY_AFTER_REQUIRED');", '  return response.json();', '}',
    ...Array.from({ length: 100 }, (_, index) => `// presentation helper ${index}: default spacing is twelve pixels.`),
  ];
  const raw = source('invoice-sdk', 'Invoice TypeScript SDK v3', code);
  const start = code.indexOf('export async function submitInvoice(request: RetryRequest): Promise<Invoice> {') + 1;
  const b = entry('invoice-submit-api', 'Invoice submit API contract', 'POST submitInvoice accepts RetryRequest. Preserve exact route, request cancellation, nullish retryAfterMs default, and different 409/429 errors; consult source.', [raw], [[start, start + 10]]);
  return { id: 'long-code-interface', label: '长代码接口、空值默认和错误分支', query: '核对 submitInvoice 的准确路由、HTTP 方法、幂等请求头、取消信号、retryAfterMs 默认值与 409/429 错误。', sources: [raw], compilation: compilation([b]),
    reads: [{ layer: 'B', id: b.id, reason: 'api-contract' }, { layer: 'A', id: raw.id, reason: 'exact-code', startLine: start, endLine: start + 10, completeRange: true }],
    gold: [{ layer: 'A', id: raw.id, sourceVersion: 1, startLine: start, endLine: start + 10, fragments: ["'/api/v3/invoices:submit'", "method: 'POST'", "'Idempotency-Key': request.requestId", 'signal: request.signal', 'request.retryAfterMs ?? 1250', "response.status === 409) throw new Error('DUPLICATE_INVOICE')", "response.status === 429) throw new Error('RETRY_AFTER_REQUIRED')"] }], noiseIds: [], triggers: ['exact'] };
}

